import{z as i,x as o,o as t,c as p,q as r,j as n,D as a,d as A,s,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"期权行权与交割","description":"","frontmatter":{"title":"期权行权与交割","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/option-exercise-settlement.md","filePath":"quant/option-exercise-settlement.md","lastUpdated":1791063341000}'),d={name:"quant/option-exercise-settlement.md"};function C(m,E,h,u,D,c){const l=o("Mermaid");return t(),p("div",null,[E[2]||(E[2]=r('<h1 id="期权行权与交割" tabindex="-1">期权行权与交割 <a class="header-anchor" href="#期权行权与交割" aria-label="Permalink to &quot;期权行权与交割&quot;">​</a></h1><div class="epigraph"><p>到期不是希腊值归零那么干净：现金交割改账户现金，实物交割改股票持仓并立即进入保证金、借券与做空规则。回测若在到期日把期权市值抹成零，会漏掉隔夜的股票腿。</p><footer>—— 据 OCC 交割与行权说明；交易所美式/欧式行权与结算惯例整理</footer></div><p>上一课<a href="/quant/short-sale-uptick">做空规则与报升</a>过滤股票空头。期权到期可以把你变成股票多头或空头，过滤器必须再跑一遍。本课补行权与交割对回测状态机的冲击。不重写 Black–Scholes，不进入限价簿的期权复杂订单。随机分析课已经把提前行权当成最优停；本课问的是<strong>交割之后资金与证券往哪走</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纸面期权回测常用结算价把到期损益记成现金，然后仓位清空。实物交割的个股期权不是这样：行权付出行权价、收入股票（或多头被指派变成空头股票）。周末与假期使期权到期日到股票开盘之间有缺口，股票腿的第一可成交价可以远离行权价。缺口课在这里再次出现，只是触发器是交割日历而不是维持线。现金交割的指数期权没有股票腿，但结算价规则（开盘交割 vs 收盘）会改变最后一天的损益，用收盘当结算是常见前视或错记。</p><p><span class="marginnote">术语翻译：现金交割就是「到期只按结算价算一笔钱进出账户」，像赌局结账；实物交割则是「真的换货」——行权方付行权价收股票，被指派方收钱交股票。一旦收了股票，保证金、借券、涨跌停这些股票世界的规则立刻适用。</span></p><h3 id="行权不是自动按理论价平仓" tabindex="-1">行权不是自动按理论价平仓 <a class="header-anchor" href="#行权不是自动按理论价平仓" aria-label="Permalink to &quot;行权不是自动按理论价平仓&quot;">​</a></h3><p>虚值期权通常放弃，实值欧式自动行权有阈值规则，美式可能被提前指派（尤其临近分红）。回测按理论值在到期日「平掉」而不走 OCC 的自动行权阈值，会在深度实值与临界实值上记错股票库存。库存一旦出现，借券、报升、涨跌停立刻适用。</p><p><span class="marginnote">提前指派常发生在分红前。财务课的除权日在这里变成期权库存事件：你可能在除权前被指派成空头股票，必须融券。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>到期与行权写入日历：合约类型（现金/实物、美式/欧式）、结算价定义、自动行权阈值、交割日。到期日终：现金交割只更新现金；实物交割更新股票数量与应付现金，下一交易日按股票规则检查保证金与可借。禁止在到期日用期权中间价清仓来代替交割，除非你真的在到期前平仓且该平仓可成交。提前指派按当时已公布的分红与规则触发，不得用事后是否真的被指派的完整清单而不含随机性——至少要声明假设（总是被指派 / 从不 / 按公开阈值）。</p><p>结算周期：股票交割仍走 T+\\(n\\)，行权应付资金有自己的 OCC 时钟，两条时钟都要进占用。</p><p><span class="marginnote">数字实例：若自动行权阈值设为实值 0.01 美元，一张执行价 100 的看涨在标的收于 100.005 时实值只有 0.005，低于阈值将被放弃而非行权。回测若按理论价全部行权，会多出一堆几分钱实值的股票腿，并在下一天产生本不存在的借券与保证金需求。</span></p>',13)),(t(),n(B,null,{default:a(()=>[s(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E5%88%B0%E6%9C%9F%E6%88%96%E8%A1%8C%E6%9D%83%22%5D%20--%3E%20CASHSET%5B%22%E7%8E%B0%E9%87%91%E4%BA%A4%E5%89%B2%EF%BC%9A%E5%8F%AA%E6%94%B9%E7%8E%B0%E9%87%91%22%5D%0A%20%20EXP%20--%3E%20PHYS%5B%22%E5%AE%9E%E7%89%A9%E4%BA%A4%E5%89%B2%EF%BC%9A%E6%94%B9%E8%82%A1%E7%A5%A8%E5%BA%93%E5%AD%98%22%5D%0A%20%20PHYS%20--%3E%20MARGIN%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%20%E5%80%9F%E5%88%B8%20%E6%8A%A5%E5%8D%87%22%5D%0A%20%20MARGIN%20--%3E%20GAP%5B%22%E4%B8%8B%E4%B8%80%E5%8F%AF%E6%88%90%E4%BA%A4%E4%BB%B7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"深度实值个股期权在到期若被自动行权，周五收盘你还在看期权净值，周一开盘已经是股票加减现金。中间的周末缺口按股票第一可成交价记账。现金交割指数期权没有这只腿，但开盘交割窗口的结算价不是周五收盘；用错结算价会把到期周的假 alpha 做出来。提前指派与分红日历对齐，假设要写死。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"期权策略的纸面收益常把最后一天的希腊值衰减算进去，却假设没有库存。实盘在到期日之后可能持有隔夜股票，事件日、涨跌停、停牌全套适用。这是资金底在衍生品上的入口：你为了「期权 alpha」被动获得了股票因子暴露和制度约束。指数期权现金交割更干净，但结算价窗口会吸引抢跑与拍卖流动性——仍不要在本课写成 LOB。",-1)),(t(),n(B,null,{default:a(()=>[s(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E5%88%B0%E6%9C%9F%20%E5%AE%9E%E5%80%BC%E7%8A%B6%E6%80%81%22%5D%20--%3E%20D%7B%22%E5%9C%A8%E8%87%AA%E5%8A%A8%E8%A1%8C%E6%9D%83%E9%98%88%E5%80%BC%E4%B9%8B%E4%B8%8A%3F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20A%5B%22%E6%94%BE%E5%BC%83%20%E5%BD%92%E9%9B%B6%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20P%5B%22%E8%A1%8C%E6%9D%83%20%E8%BF%9B%E5%85%A5%E4%BA%A4%E5%89%B2%22%5D%0A%20%20P%20--%3E%20C%7B%22%E7%8E%B0%E9%87%91%E8%BF%98%E6%98%AF%E5%AE%9E%E7%89%A9%3F%22%7D%0A%20%20C%20--%3E%7C%22%E7%8E%B0%E9%87%91%22%7C%20C1%5B%22%E5%8F%AA%E6%94%B9%E8%B4%A6%E6%88%B7%E7%8E%B0%E9%87%91%22%5D%0A%20%20C%20--%3E%7C%22%E5%AE%9E%E7%89%A9%20%E5%A4%9A%E5%A4%B4%22%7C%20P1%5B%22%E4%BB%98%E8%A1%8C%E6%9D%83%E4%BB%B7%20%E6%94%B6%E8%82%A1%E7%A5%A8%22%5D%0A%20%20C%20--%3E%7C%22%E5%AE%9E%E7%89%A9%20%E7%A9%BA%E5%A4%B4%E8%A2%AB%E6%8C%87%E6%B4%BE%22%7C%20P2%5B%22%E6%94%B6%E8%A1%8C%E6%9D%83%E4%BB%B7%20%E4%BA%A4%E8%82%A1%E7%A5%A8%20%E5%8F%98%E7%A9%BA%E5%A4%B4%22%5D%0A%20%20P1%20--%3E%20M%5B%22%E6%AC%A1%E6%97%A5%E8%BF%87%E4%BF%9D%E8%AF%81%E9%87%91%20%E5%8F%AF%E5%80%9F%20%E6%8A%A5%E5%8D%87%22%5D%0A%20%20P2%20--%3E%20M%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">下一课期货展期是同一类日历问题：合约到期必须换仓，否则进入交割。期权是行权库存，期货是展期或交割。</span></p><p>到期日按合约类型更新：现金交割只动现金与结算价定义（开盘交割不得用收盘价）；实物交割变动股票库存与应付行权价，次一交易日按股票制度跑保证金、借券、报升、涨跌停。禁止用到期日期权中间价清仓代替交割，除非平仓委托确实发生且可成交。分红前美式提前指派按声明的假设触发，并与除权日对齐。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重推导美式提前行权的最优停，不写期权做市义务。下一课<a href="/quant/futures-roll-calendar">期货交割与展期日历</a>收制度课，并交给限价簿。后课默认：期权到期按交割类型更新现金或股票；股票腿立即受前序全部制度约束。</p><p>后课期货展期是另一类到期日历。本课实物交割的股票腿，次日立即受保证金、借券、报升、涨跌停约束。现金交割的结算价定义写错，最后一日损益全错。用期权中间价抹零代替交割，从本课起视为漏记库存。</p><p>后课默认期权到期按交割类型更新现金或股票；股票腿立即受保证金、借券、报升与涨跌停约束。</p><p>自动行权阈值以下的轻度实值可能被放弃，阈值以上变成股票。回测按当时 OCC 或交易所阈值处理，不要按理论价全部行权。由此产生的股票空头，周一开盘先过可借与报升，再谈要不要立刻平掉。</p><p><span class="marginnote">常见误区：初学者容易以为「到期日最干净，一切归零」。实际上实物交割让你周五收盘还拿着期权，周一开盘已经是股票多头或空头，中间还隔着周末缺口；把期权市值抹成零，漏掉的正是这条隔夜股票腿。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>现金交割改现金；实物交割制造股票库存。</li><li>用期权市值抹零会漏掉隔夜股票腿与缺口。</li><li>自动行权阈值与提前指派必须按当时规则。</li><li>股票腿立刻走保证金、借券、报升、涨跌停。</li><li>结算价定义（开盘/收盘）写错即错记最后一日损益。</li><li>出处：OCC 行权交割说明；交易所结算惯例。</li></ul>',10))])}const P=i(d,[["render",C]]);export{F as __pageData,P as default};
